// Copies the normative OLIP files from protocol/ into the site and generates the
// spec pages that are derived from them. Run automatically before every build.
// Single source of truth: protocol/. Never edit the generated files by hand.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const proto = path.join(root, 'protocol');
const out = path.join(root, 'static', 'spec', '0.1');
const dl = path.join(root, 'static', 'downloads');
const GEN = '<!-- GENERATED by scripts/sync-spec.mjs from protocol/. Do not edit; edit protocol/ instead. -->';

const rm = (p) => fs.rmSync(p, {recursive: true, force: true});
const mk = (p) => fs.mkdirSync(p, {recursive: true});
const sha = (buf) => crypto.createHash('sha256').update(buf).digest('hex');
// Reproducible zips: fixed timestamps, sorted entries, no extra attributes, so the same source always
// gives the same SHA-256. The timestamp is the release date in src/data/release.json.
const RELEASE = JSON.parse(fs.readFileSync(path.join(root, 'src', 'data', 'release.json'), 'utf8'));
const ZIP_TIME = new Date(`${RELEASE.kit_timestamp}`);
function walk(dir, rel = '') {
  return fs.readdirSync(path.join(dir, rel), {withFileTypes: true}).flatMap((d) => {
    const r = rel ? `${rel}/${d.name}` : d.name;
    return d.isDirectory() ? walk(dir, r) : [r];
  });
}
function detZip(zipPath, cwd, entries) {
  const files = entries.flatMap((e) => (fs.statSync(path.join(cwd, e)).isDirectory() ? walk(cwd, e) : [e]))
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const f of files) fs.utimesSync(path.join(cwd, f), ZIP_TIME, ZIP_TIME);
  rm(zipPath);
  execFileSync('zip', ['-X', '-D', '-q', zipPath, '-@'], {cwd, input: files.join('\n') + '\n', env: {...process.env, TZ: 'UTC'}});
}


rm(out); rm(dl); mk(out); mk(dl);

function copyDir(src, dst, filter = () => true) {
  mk(dst);
  for (const f of fs.readdirSync(src).sort()) {
    if (filter(f)) fs.copyFileSync(path.join(src, f), path.join(dst, f));
  }
}
copyDir(path.join(proto, 'schemas'), path.join(out, 'schemas'), (f) => f.endsWith('.json'));
copyDir(path.join(proto, 'examples'), path.join(out, 'examples'), (f) => f.endsWith('.json'));
mk(path.join(out, 'openapi'));
fs.copyFileSync(path.join(proto, 'openapi', 'olip-0.1.json'), path.join(out, 'openapi', 'olip-0.1.json'));
fs.copyFileSync(path.join(proto, 'spec', 'status-machine.json'), path.join(out, 'status-machine.json'));
fs.copyFileSync(path.join(proto, 'spec', 'taxonomy-0.1.json'), path.join(out, 'taxonomy-0.1.json'));

// OLIP 0.2 additions: schemas and examples under /spec/0.2/.
const out02 = path.join(root, 'static', 'spec', '0.2');
rm(out02);
copyDir(path.join(proto, 'schemas-0.2'), path.join(out02, 'schemas'), (f) => f.endsWith('.json'));
copyDir(path.join(proto, 'examples-0.2'), path.join(out02, 'examples'), (f) => f.endsWith('.json'));

// Proposal P-02 (not part of OLIP 0.1): schema served at the URL its $id names, examples beside the proposal.
const p02 = path.join(proto, 'proposals', 'v12');
const p02Out = path.join(root, 'static', 'spec', 'proposals', 'p-02');
const p02Schema = path.join(root, 'static', 'schemas', 'intake-capability-card');
rm(path.join(root, 'static', 'spec', 'proposals')); rm(path.join(root, 'static', 'schemas'));
copyDir(path.join(p02, 'examples'), path.join(p02Out, 'examples'), (f) => f.endsWith('.json'));
copyDir(path.join(p02, 'schemas'), path.join(p02Out, 'schemas'), (f) => f.endsWith('.json'));
mk(p02Schema);
fs.copyFileSync(path.join(p02, 'schemas', 'intake-capability-card-0.1-draft.json'), path.join(p02Schema, '0.1-draft.json'));

// Link rewriting for spec text taken from protocol/.
function rewrite(md) {
  return md
    .replace(/`schemas\/\*\.json`/g, '[`schemas/*.json`](/spec/downloads/#json-schemas)')
    .replace(/`schemas\/([a-z-]+\.json)`/g, '[`$1`](pathname:///spec/0.1/schemas/$1)')
    .replace(/\(`([a-z-]+\.json)`\)/g, (m, f) =>
      fs.existsSync(path.join(proto, 'schemas', f)) ? `([\`${f}\`](pathname:///spec/0.1/schemas/${f}))` : m)
    .replace(/`spec\/status-machine\.json`/g, '[`status-machine.json`](pathname:///spec/0.1/status-machine.json)')
    .replace(/(?<!\[)`status-machine\.json`/g, '[`status-machine.json`](pathname:///spec/0.1/status-machine.json)')
    .replace(/`spec\/taxonomy-0\.1\.json`/g, '[`taxonomy-0.1.json`](pathname:///spec/0.1/taxonomy-0.1.json)')
    .replace(/`openapi\/olip-0\.1\.json`/g, '[`openapi/olip-0.1.json`](pathname:///spec/0.1/openapi/olip-0.1.json)')
    .replace(/See `governance\/VERSIONING\.md`/g, 'See [Versioning and compatibility](/spec/versioning/)')
    .replace(/\(see `governance\/NAME-AND-TRADEMARK-CLEARANCE\.md`\)/g, '(see [Governance: name and trademark](/governance/#name-and-trademark))')
    .replace(/See `governance\/DECISION-LOG\.md`/g, 'See the [decision log](/governance/#decision-log)')
    .replace(/\(see `governance\/CONFORMANCE-AND-MARK-RULES\.md`\)/g, '(see [conformance and mark rules](/governance/#conformance-and-mark-rules))')
    .replace(/\(`governance\/SECURITY-POLICY-DRAFT\.md`\)/g, '([security policy](/security/))')
    .replace(/Full threat model: `spec\/THREAT-MODEL\.md`\. Developer checklist: `docs\/SECURITY-CHECKLIST\.md`\./g,
      'Full threat model: [Threat model](/spec/threat-model/). Developer checklist: [Privacy and security checklist](/docs/implementing/privacy-and-security/#checklist).')
    .replace(/\(see `docs\/BASELINE-AUDIT\.md` §4\)/g, '(this case was found in the sponsor\'s own engine audit)')
    .replace(/\(see `docs\/SCORECARDS\.md`\)/g, '');
}

// 1. Full specification text.
let spec = fs.readFileSync(path.join(proto, 'spec', 'OLIP-0.1-DRAFT.md'), 'utf8');
spec = spec
  .replace(/^# .*\n/, '')
  .replace('**Status:** DRAFT for review. Not published. Not adopted by anyone.', '**Status:** DRAFT for review. Not adopted by anyone.')
  .replace('**Editor:** the sponsor (Digital Crossings Inc. / Digital Crossings Inc.) until a council exists.', '**Editor:** the initial sponsor (Digital Crossings Inc.) until an independent editorial group exists.')
  .replace('**Machine-readable parts (normative):** `schemas/*.json` (JSON Schema 2020-12), `spec/status-machine.json`, `spec/taxonomy-0.1.json`, `openapi/olip-0.1.json`.',
    '**Machine-readable parts (normative):** `schemas/*.json` (JSON Schema 2020-12), `spec/status-machine.json`, `spec/taxonomy-0.1.json`, `openapi/olip-0.1.json`. All are listed on [Downloads](/spec/downloads/).');
spec = rewrite(spec);
fs.writeFileSync(path.join(root, 'spec', 'olip-0.1.md'), `---
id: olip-0.1
title: OLIP 0.1 specification (draft)
sidebar_label: Full text
slug: /0.1/
description: The complete text of the OLIP 0.1 working draft, the Open Legal Intake Protocol. Normative language, six modules, operations, policy gate, errors, versioning, bindings and conformance.
---
${GEN}

# OLIP 0.1 specification (working draft)

:::caution Draft for review
This is the single canonical text of OLIP 0.1. It is a **proposed draft**: not ratified, not adopted, and not reviewed by counsel, a standards body, a bar or a regulator. It may change incompatibly before 1.0. See [Status](/spec/status/).
:::

:::note Editor's note (not part of the 0.1 text)
The 0.1 text below is kept exactly as published on 2026-11-06, so its hashes stay valid. Some statements in it describe that date: since then the sponsor granted the licenses and states that the name is cleared (2026-11-07, decisions D-11 and D-12), and optional [0.2 additions](/spec/0.2/) were published. Current facts are on [Status](/spec/status/).
:::

${spec}`);

// 1b. OLIP 0.2 additions text.
let spec02 = fs.readFileSync(path.join(proto, 'spec', 'OLIP-0.2-DRAFT.md'), 'utf8').replace(/^# .*\n/, '');
spec02 = spec02
  .replace(/`([a-z-]+\.json)`/g, (m, f) => fs.existsSync(path.join(proto, 'schemas-0.2', f)) ? `[\`${f}\`](pathname:///spec/0.2/schemas/${f})` : m)
  .replace(/`reference\/lib\/olip-core\.mjs`/g, '`reference/lib/olip-core.mjs` (in the kit)')
  .replace('See the guide at `/docs/implementing/olip-over-mcp/` on olip.ai.', 'See the guide: [OLIP over MCP](/docs/implementing/olip-over-mcp/).');
fs.writeFileSync(path.join(root, 'spec', 'olip-0.2.md'), `---
id: olip-0.2
title: OLIP 0.2 additions (draft)
sidebar_label: Full text of the 0.2 additions
slug: /0.2/
description: OLIP 0.2 = OLIP 0.1 plus key bindings, signed status webhooks and the intake capability card. Normative text, discovery, client and receiver rules, conformance checks V1 to V5.
---
${GEN}

# OLIP 0.2 additions (working draft)

:::caution Draft for review
OLIP 0.2 is a **proposed draft**: not ratified and not adopted. It changes nothing in [OLIP 0.1](/spec/0.1/) and adds three optional features. See [Status](/spec/status/).
:::

${spec02}`);

// 2. Threat model.
let tm = fs.readFileSync(path.join(proto, 'spec', 'THREAT-MODEL.md'), 'utf8');
tm = rewrite(tm.replace(/^# .*\n/, ''))
  .replace('an official name and domain (not yet owned)', 'the olip.ai domain (registered 2026-11-07); name and trademark clearance not done');
fs.writeFileSync(path.join(root, 'spec', 'threat-model.md'), `---
id: threat-model
title: Threat model (draft)
description: STRIDE-style threat model for OLIP 0.1 with controls, the conformance test that covers each, and residual risk.
---
${GEN}

# OLIP 0.1 threat model

${tm}`);

// 3. Status machine as a readable page.
const sm = JSON.parse(fs.readFileSync(path.join(proto, 'spec', 'status-machine.json'), 'utf8'));
const esc = (s) => String(s).replace(/\|/g, '\\|');
let smd = `---
id: status-machine
title: Status machine (normative)
description: Every OLIP 0.1 handoff state, its meaning, and every allowed transition with its permitted sources and required evidence.
---
${GEN}

# Status machine

${esc(sm.description)}

Machine-readable file: [\`status-machine.json\`](pathname:///spec/0.1/status-machine.json).

## Sources

| Source | Meaning |
|---|---|
${Object.entries(sm.sources).map(([k, v]) => `| \`${k}\` | ${esc(v)} |`).join('\n')}

## States

| State | Terminal | Meaning |
|---|---|---|
${Object.entries(sm.states).map(([k, v]) => `| \`${k}\` | ${v.terminal ? 'yes' : 'no'} | ${esc(v.meaning)} |`).join('\n')}

States that mean something left the host: ${(sm.transmitted_states || []).map((s) => `\`${s}\``).join(', ')}.

## Allowed transitions

Anything not listed here MUST be refused with \`OLIP_INVALID_TRANSITION\` or \`OLIP_EVENT_SOURCE_FORBIDDEN\`.

| From | To | Allowed sources | Required evidence |
|---|---|---|---|
${sm.transitions.map((t) => `| \`${t.from}\` | \`${t.to}\` | ${t.sources.map((s) => `\`${s}\``).join(', ')} | ${(t.evidence || []).map((s) => `\`${s}\``).join(', ')} |`).join('\n')}
`;
if (sm.recipient_event_types) {
  smd += `\n## Recipient event types\n\nEvents that only an authenticated recipient (its intake system or a person at the firm) may record: ${sm.recipient_event_types.map((s) => `\`${s}\``).join(', ')}. The calling agent can never record them.\n`;
}
fs.writeFileSync(path.join(root, 'spec', 'status-machine.md'), smd);

// 4. Download bundle (spec files + reference kit) and checksums.
const stage = path.join(root, '.olip-kit-stage', 'olip-0.2-draft');
rm(path.join(root, '.olip-kit-stage')); mk(stage);
execFileSync('cp', ['-r', ...['README.md', 'package.json', 'package-lock.json', '.gitignore', 'spec', 'schemas', 'schemas-0.2', 'openapi', 'examples', 'examples-0.2', 'mcp', 'reference', 'alt-python', 'conformance', 'tests', 'scripts', 'governance']
  .map((f) => path.join(proto, f)), stage]);
rm(path.join(stage, 'tests', 'proposal-p02.test.mjs')); // P-02 is not part of the 0.1 kit
fs.mkdirSync(path.join(stage, 'docs'));
for (const f of ['QUICKSTART.md', 'SECURITY-CHECKLIST.md']) fs.copyFileSync(path.join(proto, 'docs', f), path.join(stage, 'docs', f));
fs.writeFileSync(path.join(stage, 'NOTICE.txt'),
  'OLIP (Open Legal Intake Protocol) draft kit: OLIP 0.1 plus the 0.2 additions. Downloaded from https://olip.ai/spec/downloads/\n' +
  'Status: draft for review; not an adopted standard. All data is fictional.\n' +
  'Licenses (granted 2026-11-07 by the initial sponsor, Digital Crossings Inc.): specification text, schemas, status machine and\n' +
  'taxonomy under CC BY 4.0 with the OWFa 1.0 patent commitment; reference code and conformance suite under Apache License 2.0;\n' +
  'fictional examples under CC0 1.0. See https://olip.ai/license/\n');
execFileSync('find', [stage, '-name', '__pycache__', '-prune', '-exec', 'rm', '-rf', '{}', ';']);
execFileSync('find', [stage, '-name', 'node_modules', '-prune', '-exec', 'rm', '-rf', '{}', ';']);
const kitZip = path.join(dl, 'olip-0.2-draft-kit.zip');
detZip(kitZip, path.dirname(stage), ['olip-0.2-draft']);
rm(path.join(root, '.olip-kit-stage'));

const schemaZip = path.join(dl, 'olip-0.1-schemas.zip');
detZip(schemaZip, out, ['schemas', 'examples', 'openapi', 'status-machine.json', 'taxonomy-0.1.json']);
const schemaZip02 = path.join(dl, 'olip-0.2-schemas.zip');
detZip(schemaZip02, out02, ['schemas', 'examples']);

// 5. Downloads page with sizes and SHA-256 checksums.
const list = (dir, rel) => fs.readdirSync(dir).sort().map((f) => {
  const b = fs.readFileSync(path.join(dir, f));
  return {f, href: `${rel}/${f}`, size: b.length, sha: sha(b)};
});
const fmt = (n) => (n > 1024 ? `${(n / 1024).toFixed(1)} KB` : `${n} B`);
const row = (x, desc = '') => `| [\`${x.f}\`](pathname://${x.href}) | ${desc} | ${fmt(x.size)} | \`${x.sha.slice(0, 16)}…\` |`;
const schemaDesc = {};
for (const x of list(path.join(out, 'schemas'), '/spec/0.1/schemas')) {
  try { schemaDesc[x.f] = JSON.parse(fs.readFileSync(path.join(out, 'schemas', x.f), 'utf8')).title || ''; } catch { schemaDesc[x.f] = ''; }
}
const exDesc = {};
for (const x of list(path.join(out, 'examples'), '/spec/0.1/examples')) {
  try { const j = JSON.parse(fs.readFileSync(path.join(out, 'examples', x.f), 'utf8')); exDesc[x.f] = `${j.description || ''} (schema: \`${j.schema}\`)`; } catch { exDesc[x.f] = ''; }
}
const checksums = [];
const all = [
  ...list(dl, '/downloads'),
  ...list(path.join(out, 'schemas'), '/spec/0.1/schemas'),
  ...list(path.join(out, 'examples'), '/spec/0.1/examples'),
  ...list(path.join(out, 'openapi'), '/spec/0.1/openapi'),
  ...['status-machine.json', 'taxonomy-0.1.json'].map((f) => { const b = fs.readFileSync(path.join(out, f)); return {f, href: `/spec/0.1/${f}`, size: b.length, sha: sha(b)}; }),
  ...list(path.join(out02, 'schemas'), '/spec/0.2/schemas'),
  ...list(path.join(out02, 'examples'), '/spec/0.2/examples'),
];
for (const x of all) checksums.push(`${x.sha}  ${x.href}`);
fs.writeFileSync(path.join(dl, 'SHA256SUMS.txt'), checksums.join('\n') + '\n');

const dlList = list(dl, '/downloads').filter((x) => x.f !== 'SHA256SUMS.txt');
fs.writeFileSync(path.join(root, 'spec', 'downloads.md'), `---
id: downloads
title: Schemas and downloads
description: Download the OLIP 0.1 and 0.2 draft JSON Schemas, OpenAPI 3.1 document, status machine, starter taxonomy, fictional examples and the reference kit, with SHA-256 checksums.
---
${GEN}

# Schemas and downloads

Every file here is part of the **OLIP 0.1 draft** or the **OLIP 0.2 additions**. URLs under \`/spec/0.1/\` and \`/spec/0.2/\` stay stable for each line; a new minor line gets a new folder (see [Versioning](/spec/versioning/)). Each schema's \`$id\` is its URL on this site.

:::note Licensing
Granted 2026-11-07: CC BY 4.0 with the OWFa 1.0 patent commitment for spec text and schemas, Apache 2.0 for code, CC0 1.0 for fictional examples. See [Licensing](/license/).
:::

## Bundles

| File | Contents | Size | SHA-256 |
|---|---|---|---|
${dlList.map((x) => row(x, x.f.includes('kit') ? 'Everything needed to run the fictional quickstart: OLIP 0.1 and the 0.2 additions (spec, schemas, OpenAPI, examples), Node reference mock endpoint (0.1 + 0.2), Python second endpoint (0.1 only), MCP adapter, conformance suite and tests' : x.f.includes('0.2') ? 'OLIP 0.2 additions: schemas and examples only' : 'OLIP 0.1: schemas, examples, OpenAPI, status machine and taxonomy only')).join('\n')}

Full checksums: [\`SHA256SUMS.txt\`](pathname:///downloads/SHA256SUMS.txt).

## JSON Schemas

JSON Schema draft 2020-12. Shared definitions live in \`common.json\`.

| File | Title | Size | SHA-256 |
|---|---|---|---|
${list(path.join(out, 'schemas'), '/spec/0.1/schemas').map((x) => row(x, schemaDesc[x.f])).join('\n')}

## OpenAPI, status machine and taxonomy

| File | What | Size | SHA-256 |
|---|---|---|---|
${row(list(path.join(out, 'openapi'), '/spec/0.1/openapi')[0], 'HTTPS binding, OpenAPI 3.1')}
${row({f: 'status-machine.json', href: '/spec/0.1/status-machine.json', ...(() => { const b = fs.readFileSync(path.join(out, 'status-machine.json')); return {size: b.length, sha: sha(b)}; })()}, 'Normative states and transitions ([readable version](/spec/status-machine/))')}
${row({f: 'taxonomy-0.1.json', href: '/spec/0.1/taxonomy-0.1.json', ...(() => { const b = fs.readFileSync(path.join(out, 'taxonomy-0.1.json')); return {size: b.length, sha: sha(b)}; })()}, 'Starter matter codes. Every SALI LMSS mapping is \`unmapped_pending_review\`')}

## Fictional examples

Each example is wrapped as \`{schema, fictional, description, example}\` and validates against the named schema (test: \`npm test\` in the kit). All people, firms, license numbers and addresses are fictional.

| File | What | Size | SHA-256 |
|---|---|---|---|
${list(path.join(out, 'examples'), '/spec/0.1/examples').map((x) => row(x, exDesc[x.f])).join('\n')}

## OLIP 0.2 additions

Normative text: [OLIP 0.2 additions](/spec/0.2/). The 0.2 schemas reference the 0.1 \`common.json\` and \`status-event.json\` by absolute URL.

| File | Title | Size | SHA-256 |
|---|---|---|---|
${list(path.join(out02, 'schemas'), '/spec/0.2/schemas').map((x) => row(x, (() => { try { return JSON.parse(fs.readFileSync(path.join(out02, 'schemas', x.f), 'utf8')).title || ''; } catch { return ''; } })())).join('\n')}

### 0.2 fictional examples

Generated by running the reference endpoint (\`scripts/make-examples-0.2.mjs\` in the kit). Each file says whether its signature verifies.

| File | What | Size | SHA-256 |
|---|---|---|---|
${list(path.join(out02, 'examples'), '/spec/0.2/examples').map((x) => row(x, (() => { try { const j = JSON.parse(fs.readFileSync(path.join(out02, 'examples', x.f), 'utf8')); return `${j.note || ''}${j.schema ? ` (schema: \`${j.schema}\`)` : ''}`; } catch { return ''; } })())).join('\n')}
`);

// 6. Lists used by the in-browser validator page.
mk(path.join(root, 'src', 'data'));
fs.writeFileSync(path.join(root, 'src', 'data', 'spec-files.json'), JSON.stringify({
  schemas: fs.readdirSync(path.join(out, 'schemas')).sort().map((f) => ({file: f, name: f.replace(/\.json$/, ''), title: schemaDesc[f] || ''})),
  examples: fs.readdirSync(path.join(out, 'examples')).sort().map((f) => {
    const j = JSON.parse(fs.readFileSync(path.join(out, 'examples', f), 'utf8'));
    return {file: f, schema: j.schema, description: j.description || ''};
  }),
}, null, 2) + '\n');


// 7. Conformance results shown on /conformance/ (sponsor self-test; regenerate with `npm test` in protocol/).
{
  const res = (f) => JSON.parse(fs.readFileSync(path.join(proto, 'conformance', 'results', f), 'utf8'));
  const runs = {node: res('node-endpoint.json'), python: res('python-endpoint.json')};
  const suite = fs.readFileSync(path.join(proto, 'conformance', 'run.mjs'));
  const profiles = {};
  for (const [name, r] of Object.entries(runs)) {
    for (const c of r.results) {
      const p = (profiles[c.profile] ||= {profile: c.profile, checks: 0, node: {pass: 0, fail: 0, skip: 0}, python: {pass: 0, fail: 0, skip: 0}});
      if (name === 'node') p.checks += 1;
      p[name][c.result] += 1;
    }
  }
  const pick = (r) => ({label: r.label, olip_version: r.olip_version, mode: r.mode, ran_at: r.ran_at, seconds: r.seconds, pass: r.pass, fail: r.fail, skip: r.skip});
  const ids = runs.node.results.map((c) => c.id);
  fs.writeFileSync(path.join(root, 'src', 'data', 'conformance.json'), JSON.stringify({
    suite: {file: 'conformance/run.mjs', sha256: sha(suite), kit: '/downloads/olip-0.2-draft-kit.zip'},
    runner: 'sponsor self-test on the sponsor\'s machine with fictional data',
    independent_reproductions: [],
    total_checks: ids.length,
    runs: {node: pick(runs.node), python: pick(runs.python)},
    profiles: Object.values(profiles),
    checks: runs.node.results.map((c) => ({id: c.id, profile: c.profile, name: c.name,
      node: c.result, python: (runs.python.results.find((x) => x.id === c.id) || {}).result || 'not_run',
      note: [c.reason, (runs.python.results.find((x) => x.id === c.id) || {}).reason].filter(Boolean).join(' / ') || null})),
  }, null, 2) + '\n');
}

// 8. Precompiled schema validators for the in-browser validator page. The site's Content-Security-Policy has no
// 'unsafe-eval', so Ajv cannot compile schemas in the browser; it compiles them here, at build time, instead.
{
  const {createRequire} = await import('node:module');
  const req = createRequire(path.join(root, 'package.json'));
  const Ajv2020 = req('ajv/dist/2020').default;
  const addFormats = req('ajv-formats').default;
  const standaloneCode = req('ajv/dist/standalone').default;
  const {_} = req('ajv');
  const ajvS = new Ajv2020({allErrors: true, strict: false, code: {source: true, formats: _`require("ajv-formats/dist/formats").fullFormats`}});
  addFormats(ajvS);
  const exportsMap = {};
  for (const f of fs.readdirSync(path.join(proto, 'schemas')).sort()) {
    const sch = JSON.parse(fs.readFileSync(path.join(proto, 'schemas', f), 'utf8'));
    ajvS.addSchema(sch);
    exportsMap[f.replace(/\.json$/, '').replace(/-/g, '_')] = sch.$id;
  }
  fs.writeFileSync(path.join(root, 'src', 'data', 'validators-0.1.js'),
    '// GENERATED by scripts/sync-spec.mjs from protocol/schemas. Do not edit.\n' + standaloneCode(ajvS, exportsMap));
}

console.log(`sync-spec: ${all.length} files published under static/, spec pages generated.`);
